#include "4DPluginAPI.h"
#include "4DPlugin.h"
#include <mutex>
#include <vector>
#include <sys/stat.h>

#pragma mark Context

std::map<uint32_t, FILE*> fopen_contexts;
std::mutex fopen_contexts_mutex;

uint32_t fopen_context_add(FILE *file)
{
    if(file)
    {
        std::lock_guard<std::mutex> lock(fopen_contexts_mutex);
        static uint32_t next_id = 1;
        uint32_t id = next_id++;
        fopen_contexts.insert(std::map<uint32_t, FILE*>::value_type(id, file));
        return id;
    }
    return 0;
}

FILE *fopen_context_get(uint32_t i)
{
    std::lock_guard<std::mutex> lock(fopen_contexts_mutex);
    std::map<uint32_t, FILE*>::iterator pos = fopen_contexts.find(i);
    return (pos != fopen_contexts.end()) ? pos->second : NULL;
}

void fopen_context_remove(uint32_t i)
{
    std::lock_guard<std::mutex> lock(fopen_contexts_mutex);
    std::map<uint32_t, FILE*>::iterator pos = fopen_contexts.find(i);
    if(pos != fopen_contexts.end())
    {
        FILE *file = pos->second;
        fclose(file);
        fopen_contexts.erase(pos);
    }
}

#pragma mark Startup / Exit

bool IsProcessOnExit()
{
    C_TEXT name;
    PA_long32 state, time;
    PA_GetProcessInfo(PA_GetCurrentProcessNumber(), name, &state, &time);
    CUTF16String procName(name.getUTF16StringPtr());
    CUTF16String exitProcName((PA_Unichar *)"$\x0x\x0x\x0\x0\x0");
    return (!procName.compare(exitProcName));
}

void OnExit()
{
    std::lock_guard<std::mutex> lock(fopen_contexts_mutex);
    for(std::map<uint32_t, FILE*>::iterator i = fopen_contexts.begin(); i != fopen_contexts.end(); i++)
    {
        FILE *file = i->second;
        fclose(file);
    }
    fopen_contexts.clear();
}

void OnCloseProcess()
{
    if(IsProcessOnExit())
    {
        OnExit();
    }
}

void OnStartup()
{
    // No action needed on startup
}

