void fwrite(sLONG_PTR *pResult, PackagePtr pParams)
{
    C_LONGINT Param1;
    C_BLOB Param2;
    C_LONGINT returnValue;

    Param1.fromParamAtIndex(pParams, 1);
    Param2.fromParamAtIndex(pParams, 2);

    FILE *f = fopen_context_get(Param1.getIntValue());
    if(f == NULL)
    {
        returnValue.setIntValue(-1); // Error: Invalid file ID
        returnValue.setReturn(pResult);
        return;
    }

    size_t bytesToWrite = Param2.getBytesLength();
    const uint8_t *data = Param2.getBytesPtr();
    size_t bytesWritten = fwrite(data, sizeof(uint8_t), bytesToWrite, f);

    if(bytesWritten != bytesToWrite)
    {
        returnValue.setIntValue(-1); // Error: fwrite failed
        returnValue.setReturn(pResult);
        return;
    }

    returnValue.setIntValue(bytesWritten);
    returnValue.setReturn(pResult);
}

void fread(sLONG_PTR *pResult, PackagePtr pParams)
{
    C_LONGINT Param1;
    C_BLOB Param2;
    C_LONGINT Param3;
    C_LONGINT returnValue;

    Param1.fromParamAtIndex(pParams, 1);
    Param3.fromParamAtIndex(pParams, 3);

    FILE *f = fopen_context_get(Param1.getIntValue());
    if(f == NULL)
    {
        returnValue.setIntValue(-1); // Error: Invalid file ID
        returnValue.setReturn(pResult);
        return;
    }

    // Get file size if length is not provided
    long cur = ftell(f);
    if(fseek(f, 0, SEEK_END) != 0)
    {
        returnValue.setIntValue(-1); // Error: fseek failed
        returnValue.setReturn(pResult);
        return;
    }
    long end = ftell(f);
    if(fseek(f, cur, SEEK_SET) != 0)
    {
        returnValue.setIntValue(-1); // Error: fseek failed
        returnValue.setReturn(pResult);
        return;
    }

    size_t size = (Param3.getIntValue() > 0) ? Param3.getIntValue() : end - cur;

    if(size > 0)
    {
        std::vector<uint8_t> buf(size);
        size_t bytesRead = fread(&buf[0], sizeof(uint8_t), size, f);
        if(bytesRead != size && !feof(f))
        {
            returnValue.setIntValue(-1); // Error: fread failed
            returnValue.setReturn(pResult);
            return;
        }
        Param2.setBytes(&buf[0], bytesRead);
        returnValue.setIntValue(bytesRead);
    }
    else
    {
        returnValue.setIntValue(0); // No data read
    }

    Param2.toParamAtIndex(pParams, 2);
    returnValue.setReturn(pResult);
}

